// CSD_RATIONALE_BEGIN
// Multi-span symbolic-math CSD for grade-school word problems.
//
// State tracked:
//   - generated: full visible token sequence (free preamble + << ... >> spans)
//   - insideConstrainedOut / currentConstrainedOut: span state from the last
//     open "<<" to the current constrained tip
//
// Observations used to choose actions:
//   - !insideConstrainedOut  → generate free reasoning text with UnconstrainedStep
//   - RenderedEndsWith(generated, "<<") → natural model delimiter observed;
//     flip to constrained mode (currentConstrainedOut := [])
//   - parser.IsCompletePrefix(currentConstrainedOut) → expression is syntactically
//     complete; call CloseConstrainedSpan to emit ">>" and return to free text
//   - otherwise inside a span → AdaptiveConstrainedStep generates the next
//     parser-valid token for the symbolic expression
//
// Multiple spans can open and close within the same budget (intermediate
// reasoning expressions + final answer).  validTokenGroups optionally carry
// number/operator/variable token hints that are softly preferred in narrow
// parser states. The task format ("Lets think step by step. … The final answer
// is <<expr>>") is steered via AppendTaskGuidance so the model uses visible
// << >> delimiters around every symbolic expression.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Unconstrained branch: the implication is vacuously true while
//   !insideConstrainedOut. When RenderedEndsWith(generated,"<<") fires we set
//   currentConstrainedOut := [], and parser.IsValidPrefix([]) holds by
//   precondition; so the invariant is re-established immediately.
//
//   CloseConstrainedSpan branch: sets insideConstrainedOut := false, making
//   the implication vacuously true; currentConstrainedOut is cleared to [].
//
//   Inner constrained branch: AdaptiveConstrainedStep returns either eosToken
//   or a token t such that parser.IsValidPrefix(currentConstrainedOut + [t]).
//   On EOS we break (invariant vacuously maintained). Otherwise
//   AppendConstrainedToken extends currentConstrainedOut by exactly t,
//   preserving IsValidPrefix. So the invariant holds at the top of the next
//   iteration.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Unconstrained branch: steps increments by 1; generated grows by at most 1
//   visible token (EOS is not appended, "<<" is one token). Bound preserved.
//
//   CloseConstrainedSpan branch: steps increments by 1; CloseConstrainedSpan
//   appends at most 1 delimiter token (">>"). Bound preserved.
//
//   Inner constrained branch: steps increments by 1; AdaptiveConstrainedStep
//   costs exactly 1 step (including EOS). AppendConstrainedToken appends at
//   most 1 visible token. Visible growth <= 1 = steps growth. Bound preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Lets think step by step. Wrap every intermediate symbolic computation in << >>. Use only the operations +, -, /, //, %, (), int(). End with: The final answer is <<symbolic expression>> where the expression uses the problem variables and numbers only.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

